use std::env
use std::fs
use std::io
use std::process

fn pad(n: int) -> string {
    let s = "${n}"
    let mut out = ""
    let mut i = s.len() as int
    while i < 6 {
        out = out + " "
        i += 1
    }
    out + s
}

fn emit(content: string, number: bool, counter: int) -> int {
    if !number {
        print(content)
        return counter
    }
    if content.len() == 0 {
        return counter
    }
    let mut c = counter
    let parts = content.split("\n")
    let n = parts.len() as int
    let mut idx = 0
    for p in parts {
        idx += 1
        if idx == n && p.len() == 0 {
            break
        }
        c += 1
        println("${pad(c)}\t${p}")
    }
    c
}

fn main() {
    let args = env::args()
    let mut number = false
    let mut files: Vec<string> = []
    let mut first = true
    for a in args {
        if first {
            first = false
            continue
        }
        if a == "-n" {
            number = true
        } else {
            files.push(a)
        }
    }
    let mut counter = 0
    let mut status = 0
    if files.len() == 0 {
        let r = io::read_to_string(io::stdin())
        match r {
            Ok(s) => { counter = emit(s, number, counter) }
            Err(e) => {}
        }
    } else {
        for f in files {
            if !fs::exists(f) {
                println("cat: ${f}: No such file")
                status = 1
                continue
            }
            match fs::read_to_string(f) {
                Ok(s) => { counter = emit(s, number, counter) }
                Err(e) => {
                    println("cat: ${f}: No such file")
                    status = 1
                }
            }
        }
    }
    if status != 0 {
        process::exit(1)
    }
}

